let settingsData=null,learningEntries=[];
function libraryError(error){const message=error?.message||'';const target=$('#workspace-error');if(target)target.textContent=message;}
async function workspaceTask(task){libraryError(null);if($('#scan-dialog-error'))$('#scan-dialog-error').textContent='';try{await task();}catch(error){libraryError(error);if($('#scan-dialog')?.open)$('#scan-dialog-error').textContent=error.message;else toast(error.message);}}
async function loadLibrary(){if(!localRuntime||!csrf)return;try{const [settings,learning]=await Promise.all([localRequest('/api/settings').then(r=>r.json()),localRequest('/api/learning').then(r=>r.json())]);settingsData=settings;learningEntries=learning.entries||[];$('#retention-days').value=settings.settings.retentionDays;$('#storage-info').textContent=`${settings.storage}. Aufträge werden ${settings.settings.retentionDays} Tage aufbewahrt.`;renderLearning();}catch(error){libraryError(error);}}
function renderLearning(){
 const host=$('#learning-list');if(!host)return;$('#workspace-view .learning-collection').classList.toggle('has-examples',Boolean(learningEntries.length));$('#learning-count').textContent=String(learningEntries.length);const rows=learningEntries.map(entry=>{
  const card=document.createElement('article');card.className='learning-entry';const head=document.createElement('div');head.className='learning-entry-head';const title=document.createElement('div');const name=document.createElement('strong');name.textContent=entry.name;const meta=document.createElement('small');meta.textContent=[entry.documentType,entry.targetLanguage].filter(Boolean).join(' · ');title.append(name,meta);const toggle=document.createElement('label');toggle.className='learning-active';const input=document.createElement('input');input.type='checkbox';input.checked=entry.active;input.setAttribute('aria-label',`${entry.name} für neue Aufträge verwenden`);input.onchange=()=>void workspaceTask(async()=>{learningEntries=(await localRequest('/api/learning/update',{id:entry.id,active:input.checked}).then(r=>r.json())).entries;renderLearning();});toggle.append(input,document.createTextNode('Anwenden'));head.append(title,toggle);const details=document.createElement('details');details.className='learning-entry-details';const detailTitle=document.createElement('summary');detailTitle.textContent='Erkannter Stil';details.append(detailTitle);const rules=document.createElement('ul');for(const rule of (entry.rules||[]).slice(0,4)){const li=document.createElement('li');li.textContent=rule;rules.append(li);}if(rules.childNodes.length)details.append(rules);else details.hidden=true;const actions=document.createElement('div');actions.className='learning-entry-actions';const preview=document.createElement('button');preview.className='text-button';preview.textContent='Muster ansehen';preview.onclick=()=>void workspaceTask(async()=>{if(card.querySelector('canvas')){card.querySelector('.learning-preview')?.remove();preview.textContent='Muster ansehen';return;}const source=await localRequest(`/api/learning/${entry.id}/source`).then(r=>r.json());const {canvas}=await sourceCanvas(source);canvas.setAttribute('role','img');canvas.setAttribute('aria-label',`Vorschau: ${entry.name}`);const frame=document.createElement('div');frame.className='learning-preview';frame.append(canvas);card.append(frame);preview.textContent='Vorschau schließen';});const remove=document.createElement('button');remove.className='text-button';remove.textContent='Entfernen';remove.onclick=()=>{if(confirm('Dieses private Muster und die gespeicherte Quelldatei entfernen?'))void workspaceTask(async()=>{learningEntries=(await localRequest('/api/learning/update',{id:entry.id,remove:true}).then(r=>r.json())).entries;renderLearning();});};actions.append(preview,remove);card.append(head,details,actions);return card;
 });if(!rows.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='Hier erscheinen deine hochgeladenen Übersetzungen.';rows.push(empty);}host.replaceChildren(...rows);
}
$('#learning-file').onchange=event=>{const files=[...event.target.files];event.target.value='';if(!files.length)return;void workspaceTask(async()=>{const status=$('#learning-status'),button=$('#learning-upload-title');status.textContent='Muster werden ausgewertet …';button.textContent='Bitte warten …';$('#learning-file').disabled=true;try{if(!localRuntime||!csrf)throw new Error('Bitte die lokale Anwendung öffnen.');if(!$('#model')?.value)throw new Error('Verbinde zuerst über KI im Header einen Modellanbieter.');let count=0;for(const file of files){await localRequest('/api/learning/upload',{files:await documentsForRequest([file]),provider:activeProvider||'chatgpt',model:$('#model').value});count++;status.textContent=`${count} von ${files.length} Mustern ausgewertet …`;}await loadLibrary();status.textContent=files.length===1?'Muster ausgewertet und gespeichert.':`${files.length} Muster ausgewertet und gespeichert.`;}finally{button.textContent='Fertige Übersetzungen hinzufügen';$('#learning-file').disabled=false;}});};
$('#retention-form').onsubmit=event=>{event.preventDefault();void workspaceTask(async()=>{settingsData=await localRequest('/api/settings',{retentionDays:Number($('#retention-days').value)}).then(r=>r.json());$('#storage-info').textContent=`${settingsData.storage}. Aufträge werden ${settingsData.settings.retentionDays} Tage aufbewahrt.`;await pollQueue();toast('Aufbewahrungsfrist gespeichert.');});};
$('#backup-download').onclick=()=>void workspaceTask(async()=>{const response=await localRequest('/api/backup',{passphrase:$('#backup-passphrase').value});downloadBlob(await response.blob(),'translateocr-backup.enc');$('#backup-passphrase').value='';toast('Verschlüsselte Sicherung erstellt.');});
$('#backup-restore').onclick=()=>void workspaceTask(async()=>{const file=$('#backup-file').files[0];if(!file)throw new Error('Bitte eine Sicherung auswählen.');if(!confirm('Die Sicherung ersetzt die aktuellen privaten Daten. Vorher eine Sicherung herunterladen. Fortfahren?'))return;await localRequest('/api/backup/restore',{data:await fileBase64(file),passphrase:$('#backup-passphrase').value,confirm:true});location.reload();});
